private void LoadRightNews()
{
    try
    {
        int languageID = ResManager.CurrentLanguageID;

        INFO_Information info = new INFO_Information();
        DataTable dt = info.GetDataTable(
            "INFO_Information_GetTop5_ByCategory",
            "@CategoryID", 125
        );

        if (dt == null || dt.Rows.Count == 0)
        {
            pnlRightNews.Visible = false;
            return;
        }

        rptRightNews.DataSource = dt;
        rptRightNews.DataBind();
        pnlRightNews.Visible = true;
    }
    catch (Exception ex)
    {
        new SystemError(SystemConfig.ConnectionString, "Detail_Info_Section1 LoadRightNews failed", ex);
        pnlRightNews.Visible = false;
    }
