protected string GetNewsUrl(object dataItem)
{
    DataRowView row = dataItem as DataRowView;
    if (row == null)
    {
        return "#";
    }

    string slug = GetStringValueRowView(row, "InformationLink");
    string categoryLink = GetStringValueRowView(row, "CategoryLink");

    if (string.IsNullOrEmpty(slug) || string.IsNullOrEmpty(categoryLink))
    {
        return "#";
    }

    if (ResManager.CurrentLanguageID == 2)
    {
        return "/en/" + categoryLink + "/" + slug;
    }

    return "/" + categoryLink + "/" + slug;
}

protected string GetNewsImage(object dataItem)
{
    DataRowView drv = dataItem as DataRowView;
    if (drv == null)
    {
        return string.Empty;
    }

    int id = ConvertToIntRowView(drv, "InformationID");
    string image = GetStringValueRowView(drv, "ThumbImageSub");
    if (string.IsNullOrEmpty(image))
    {
        image = GetStringValueRowView(drv, "ThumbImage");
    }

    if (string.IsNullOrEmpty(image))
    {
        return string.Empty;
    }

    if (image.StartsWith("/") || image.StartsWith("http", StringComparison.OrdinalIgnoreCase))
    {
        return image;
    }

    string paddedID = "000000" + id;
    string subFolder = "Information" + paddedID.Substring(paddedID.Length - 6);
    return WebGlobal.InformationThumbDirectory + "/" + subFolder + "/" + image;
}

protected string GetNewsDate(object dataItem)
{
    DataRowView drv = dataItem as DataRowView;
    if (drv == null)
    {
        return string.Empty;
    }

    DateTime dateValue;
    if (TryGetDateTimeRowView(drv, "DisplayFromDate", out dateValue) || TryGetDateTimeRowView(drv, "CreatedDate", out dateValue))
    {
        return dateValue.ToString("dd/MM/yyyy");
    }

    return string.Empty;
}

